/**
 * Recurring-issue rules. Every read is filtered by `orgId` except the job
 * sweep, which walks every non-paused rule.
 */
import { and, asc, count, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { OrgId, ProjectId, UserId } from "@/types/common";
import type { IssuePriority } from "@/types/issue";
import type { RecurringIssue, RecurrenceCadence } from "@/types/recurring-issue";

export type InsertRecurringIssueRow = {
  orgId: OrgId;
  projectId: ProjectId;
  title: string;
  priority: IssuePriority;
  assigneeId: UserId | null;
  cadence: RecurrenceCadence;
  weekday: number | null;
  timezone: string;
  startsOn: string;
  createdBy: UserId;
};

function toRecurringIssue(
  row: typeof recurringIssues.$inferSelect,
): RecurringIssue {
  return {
    id: row.id,
    orgId: row.orgId as OrgId,
    projectId: row.projectId as ProjectId,
    title: row.title,
    priority: row.priority,
    assigneeId: row.assigneeId === null ? null : (row.assigneeId as UserId),
    cadence: row.cadence,
    weekday: row.weekday,
    timezone: row.timezone,
    startsOn: row.startsOn,
    lastOccurrenceOn: row.lastOccurrenceOn,
    paused: row.paused,
    createdBy: row.createdBy as UserId,
    createdAt: toIsoTimestamp(row.createdAt),
    updatedAt: toIsoTimestamp(row.updatedAt),
  };
}

export async function insertRecurringIssue(
  input: InsertRecurringIssueRow,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      title: input.title,
      priority: input.priority,
      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy: input.createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toRecurringIssue(row);
}

/** Creation order: oldest first, id as a stable tie-break. */
export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(recurringIssues.createdAt), asc(recurringIssues.id))
    .all();

  return rows.map(toRecurringIssue);
}

export async function findRecurringIssueById(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();

  return row ? toRecurringIssue(row) : null;
}

/** Every rule counts toward the plan cap, paused ones included. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();

  return row?.value ?? 0;
}

export async function listRunnableRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(recurringIssues.createdAt), asc(recurringIssues.id))
    .all();

  return rows.map(toRecurringIssue);
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  return row ? toRecurringIssue(row) : null;
}

export async function setLastOccurrenceOn(
  orgId: OrgId,
  recurringIssueId: string,
  lastOccurrenceOn: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ lastOccurrenceOn, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  return row ? toRecurringIssue(row) : null;
}

/**
 * Recurring-issue rules: the same gates as creating an issue, plus the plan's
 * rule quota. The background job is what turns a rule into an issue.
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";
import { orgResource, projectResource, requireFound } from "./_support";

export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
  const parsed = createRecurringIssueSchema.parse(input);

  assertOrgScope(actor, parsed.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(parsed.orgId, parsed.projectId),
    "Project",
    parsed.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (parsed.assigneeId !== null) {
    const assignee = await memberRepo.findMember(parsed.orgId, parsed.assigneeId);
    if (assignee === null || assignee.status !== "active") {
      throw new Error(`Assignee ${parsed.assigneeId} is not an active member`);
    }
  }

  const org = requireFound(
    await orgRepo.findOrgById(parsed.orgId),
    "Organization",
    parsed.orgId,
  );
  const used = await recurringRepo.countRecurringIssues(parsed.orgId);
  if (wouldExceedLimit(org.plan, "recurringIssues", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more recurring issues in this organization`,
    );
  }

  return recurringRepo.insertRecurringIssue({
    orgId: parsed.orgId,
    projectId: parsed.projectId,
    title: parsed.title,
    priority: parsed.priority,
    assigneeId: parsed.assigneeId,
    cadence: parsed.cadence,
    weekday: parsed.weekday,
    timezone: parsed.timezone,
    startsOn: parsed.startsOn,
    createdBy: actor.userId,
  });
}

export async function setRecurringIssuePaused(
  actor: Actor,
  input: { orgId: OrgId; recurringIssueId: string; paused: boolean },
): Promise<RecurringIssue> {
  assertOrgScope(actor, input.orgId);

  const rule = requireFound(
    await recurringRepo.findRecurringIssueById(input.orgId, input.recurringIssueId),
    "RecurringIssue",
    input.recurringIssueId,
  );

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  return requireFound(
    await recurringRepo.setRecurringIssuePaused(
      input.orgId,
      input.recurringIssueId,
      input.paused,
    ),
    "RecurringIssue",
    input.recurringIssueId,
  );
}

export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", orgResource(orgId));
  return recurringRepo.listRecurringIssues(orgId);
}

/**
 * Files at most one issue per non-paused recurring rule: the latest occurrence
 * whose local midnight has already passed. Missed days are never back-filled.
 */
import { PermissionDeniedError } from "@/lib/permissions";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import type { UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

const logger = createLogger("recurring-issue-job");

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listRunnableRecurringIssues();

    for (const rule of rules) {
      try {
        const filed = await fileOne(rule, now);
        if (filed === "created") result.processed += 1;
        else if (filed === "failed") result.failed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring rule failed", {
          id: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

type FileOutcome = "created" | "skipped" | "failed";

async function fileOne(rule: RecurringIssue, now: Date): Promise<FileOutcome> {
  const latest = latestStartedOccurrence(rule, now);
  if (latest === null) return "skipped";
  if (rule.lastOccurrenceOn !== null && latest <= rule.lastOccurrenceOn) {
    return "skipped";
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) return "failed";
  if (isArchived(project)) return "skipped";

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  if (creator === null || creator.status !== "active") {
    await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return "failed";
  }

  const actor: Actor = {
    userId: creator.userId,
    orgId: rule.orgId,
    role: creator.role,
  };

  let assigneeId: UserId | null = null;
  if (rule.assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, rule.assigneeId);
    if (assignee !== null && assignee.status === "active") {
      assigneeId = rule.assigneeId;
    }
  }

  try {
    await createIssue(actor, {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${latest})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    }
    return "failed";
  }

  await recurringRepo.setLastOccurrenceOn(rule.orgId, rule.id, latest);
  return "created";
}

/** Latest calendar date D, on or after `startsOn`, whose local midnight is `<= now`. */
export function latestStartedOccurrence(
  rule: Pick<RecurringIssue, "cadence" | "weekday" | "timezone" | "startsOn">,
  now: Date,
): string | null {
  let cursor = calendarDate(now, rule.timezone);

  for (let step = 0; step < 14; step += 1) {
    if (cursor < rule.startsOn) return null;

    const matches =
      rule.cadence === "daily" || isoWeekday(cursor) === rule.weekday;

    if (matches && zonedMidnight(cursor, rule.timezone).getTime() <= now.getTime()) {
      return cursor;
    }

    cursor = shiftDate(cursor, -1);
  }

  return null;
}

function calendarDate(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);

  const year = part(parts, "year");
  const month = part(parts, "month");
  const day = part(parts, "day");
  return `${year}-${month}-${day}`;
}

/** ISO weekday of a `YYYY-MM-DD` date: 1 = Monday … 7 = Sunday. */
function isoWeekday(ymd: string): number {
  const [year, month, day] = ymd.split("-").map(Number);
  const utc = new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, day ?? 1));
  const dayOfWeek = utc.getUTCDay();
  return dayOfWeek === 0 ? 7 : dayOfWeek;
}

function shiftDate(ymd: string, days: number): string {
  const [year, month, day] = ymd.split("-").map(Number);
  const utc = new Date(Date.UTC(year ?? 0, (month ?? 1) - 1, (day ?? 1) + days));
  const y = utc.getUTCFullYear();
  const m = String(utc.getUTCMonth() + 1).padStart(2, "0");
  const d = String(utc.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

/**
 * UTC instant of 00:00:00 on `ymd` in `timeZone`. Two offset samples cover a
 * daylight-saving transition between the guess and the corrected instant.
 */
function zonedMidnight(ymd: string, timeZone: string): Date {
  const [year, month, day] = ymd.split("-").map(Number);
  const wallAsUtc = Date.UTC(year ?? 0, (month ?? 1) - 1, day ?? 1, 0, 0, 0);
  const first = wallAsUtc - zoneOffsetMs(new Date(wallAsUtc), timeZone);
  const second = wallAsUtc - zoneOffsetMs(new Date(first), timeZone);
  return new Date(second);
}

function zoneOffsetMs(instant: Date, timeZone: string): number {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(instant);

  const asUtc = Date.UTC(
    Number(part(parts, "year")),
    Number(part(parts, "month")) - 1,
    Number(part(parts, "day")),
    Number(part(parts, "hour")),
    Number(part(parts, "minute")),
    Number(part(parts, "second")),
  );

  return asUtc - instant.getTime();
}

function part(
  parts: readonly Intl.DateTimeFormatPart[],
  type: Intl.DateTimeFormatPartTypes,
): string {
  const found = parts.find((entry) => entry.type === type);
  return found?.value ?? "00";
}

