{"type":"SearchReplace","EditsApplied":{"old_string":"","new_string":"/**
 * Files at most one issue per non-paused recurring rule: the latest occurrence
 * whose local midnight has already passed. Missed days are never back-filled.
 */
import { PermissionDeniedError } from "@/lib/permissions";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import type { UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

const logger = createLogger("recurring-issue-job");

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listRunnableRecurringIssues();

    for (const rule of rules) {
      try {
        const filed = await fileOne(rule, now);
        if (filed === "created") result.processed += 1;
        else if (filed === "failed") result.failed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring rule failed", {
          id: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

type FileOutcome = "created" | "skipped" | "failed";

async function fileOne(rule: RecurringIssue, now: Date): Promise<FileOutcome> {
  const latest = latestStartedOccurrence(rule, now);
  if (latest === null) return "skipped";
  if (rule.lastOccurrenceOn !== null && latest <= rule.lastOccurrenceOn) {
    return "skipped";
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) return "failed";
  if (isArchived(project)) return "skipped";

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  if (creator === null || creator.status !== "active") {
    await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return "failed";
  }

  const actor: Actor = {
    userId: creator.userId,
    orgId: rule.orgId,
    role: creator.role,
  };

  let assigneeId: UserId | null = null;
  if (rule.assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, rule.assigneeId);
    if (assignee !== null && assignee.status === "active") {
      assigneeId = rule.assigneeId;
    }
  }

  try {
    await createIssue(actor, {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${latest})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    }
    return "failed";
  }

  await recurringRepo.setLastOccurrenceOn(rule.orgId, rule.id, latest);
  return "created";
}

/** Latest calendar date D, on or after `startsOn`, whose local midnight is `<= now`. */
export function latestStartedOccurrence(
  rule: Pick<RecurringIssue, "cadence" | "weekday" | "timezone" | "startsOn">,
  now: Date,
): string | null {
  let cursor = calendarDate(now, rule.timezone);

  for (let step = 0; step < 14; step += 1) {
    if (cursor < rule.startsOn) return null;

    const matches =
      rule.cadence === "daily" || isoWeekday(cursor) === rule.weekday;

    if (matches && zonedMidnight(cursor, rule.timezone).getTime() <= now.getTime()) {
      return cursor;
    }

    cursor = shiftDate(cursor, -1);
  }

  return null;
}

function calendarDate(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);

