  "/private/tmp/bench-scratch/5d3e751a-5b9c-4c18-bf59-8204e94c58eb/src/server/repositories/issue-repository.ts"
);
const projectRepo = await import(
  "/private/tmp/bench-scratch/5d3e751a-5b9c-4c18-bf59-8204e94c58eb/src/server/repositories/project-repository.ts"
);

