  title: "Daily triage",
  cadence: "weekly",
  weekday: null,
  timezone: "America/New_York",
  startsOn: "2026-02-30",
});
console.log("bad weekly+date", bad.success, bad.success ? "" : bad.error.issues.map(i => i.path.join(".")+":"+i.message));

