  orgId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
  projectId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
  title: "Daily triage",
  cadence: "daily",
  weekday: 1,
  timezone: "UTC",
  startsOn: "2026-03-05",
});
console.log("daily weekday", dailyWeekday.success);

