  orgId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
  projectId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
  title: "Daily triage",
  cadence: "daily",
  timezone: "Not/AZone",
  startsOn: "2026-03-05",
});
